        if(type==='sosa'){if(effectiveListSosaRootId)P.sosa_root_id=effectiveListSosaRootId;P.sosa_sort=st.sort||'sosa_asc';P.sosa_missing=f.sosa_missing?1:0;P.sosa_impossible=f.sosa_missing&&f.sosa_impossible?1:0;}
