    /** garde aussi les anciens réglages (state.listGender…) à jour : d'autres écrans les lisent */
    function syncListState(type,st){
        const f=st.filters||{};
        if(type==='persons')state.listGender=(f.gender||[]).length===1?f.gender[0]:'';
        if(type==='reminders'){state.listReminderMode=f.reminder_mode||'';state.listReminderCategory=f.reminder_category||'';}
        if(type==='courriers')state.listCourrierFilter=f.courrier||'';
        if(type==='sosa'){state.listSosaMissing=!!f.sosa_missing;state.listSosaImpossible=!!(f.sosa_missing&&f.sosa_impossible);state.listSosaSort=st.sort||'sosa_asc';}
        if(type==='daboville')state.listDabovilleSort=st.sort||'daboville_asc';
        if(type==='media'){state.listMediaKind=f.media_kind||'all';state.listMediaCity=lbPlaceTitle(f.media_city);state.listMediaDateFrom=f.date_from||'';state.listMediaDateTo=f.date_to||'';}
        try{persistUiState();}catch(_){}
    }
    function sortCardRows(type,rows,columns){
        const v=(state.listCardSort||{})[type]||'';if(!v)return rows;const [i,d]=v.split(':');const key=columns[Number(i)]?.[1];if(!key)return rows;
        return [...rows].sort((a,b)=>{const av=tableSortValue(type,key,a),bv=tableSortValue(type,key,b);const num=av!==''&&bv!==''&&!Number.isNaN(Number(av))&&!Number.isNaN(Number(bv));const r=num?Number(av)-Number(bv):String(av).localeCompare(String(bv),'fr',{numeric:true,sensitivity:'base'});return d==='desc'?-r:r;});
    }

