        const budgetActionsHtml=type==='research_budget'?`<div class="page-actions" style="margin-top:1rem"><button type="button" class="button" id="add-budget-item">＋ Dépense / abonnement</button></div><form id="research-budget-form" class="maintenance-panel compact reminder-create-form" hidden><input type="hidden" name="id" value=""><div class="form-grid"><label>Titre<input name="title" required placeholder="Abonnement Geneanet, acte payant…"></label><label>Catégorie<select name="category">${budgetCategories.map(([value,label])=>`<option value="${value}">${escapeHtml(label)}</option>`).join('')}</select></label><label>Montant<input name="amount" type="number" step="0.01" min="0" placeholder="0,00"></label><label>Devise<input name="currency" value="EUR" maxlength="8"></label><label>Date dépense<input name="expense_date" type="date"></label><label>Renouvellement<input name="renewal_date" type="date"></label><label>Fournisseur<input name="vendor" placeholder="Filae, Geneanet, AD…"></label><label>Note<input name="notes" placeholder="Détail utile…"></label></div><div class="page-actions"><button class="button secondary" type="button" id="cancel-budget-item">Annuler</button><button class="button" type="submit" id="research-budget-submit">Enregistrer</button></div></form><div id="research-budget-summary" class="reminder-summary-boxes"></div>`:'';
        const courrierActionsHtml=type==='courriers'?`<div class="page-actions" style="margin-top:1rem"><button type="button" class="button" id="add-courrier-item">＋ Courrier</button></div><form id="courrier-form" class="maintenance-panel compact reminder-create-form" hidden><input type="hidden" name="id" value=""><input type="hidden" name="copy_order_json" value=""><div class="form-grid"><label>Organisme<select name="organisme">${courrierOrganismes.map(([value,label])=>`<option value="${value}">${escapeHtml(label)}</option>`).join('')}</select></label><label>Destinataire précis<input name="destinataire" required placeholder="Mairie de…, Archives du…, service de reproduction…"></label><label class="span-2">Objet du courrier<input name="objet" required placeholder="Demande d’acte de naissance de…"></label><label>Date d’envoi<input name="date_envoi" type="date"></label><label>Statut<select name="statut">${courrierStatuts.map(([value,label])=>`<option value="${value}">${escapeHtml(label)}</option>`).join('')}</select></label><label>Relancer après<input data-unit="jours" name="relance_delai_jours" type="number" min="0" max="3650" value="30"></label><fieldset id="courrier-copy-order" class="courrier-copy-order span-2" hidden><legend>Bordereau de commande de copies</legend><p>Prépare un formulaire standardisé à joindre au courrier, puis imprime-le quand il est prêt.</p><div class="form-grid"><label class="span-2">Références ou documents demandés<textarea name="copy_order_references" rows="4" placeholder="Ex. Registre paroissial de…, année…, cote…, vue…"></textarea></label><label>Nombre de copies<input name="copy_order_quantity" type="number" min="1" max="999" value="1"></label><label>Support souhaité<select name="copy_order_format">${courrierCopyFormats.map(([value,label])=>`<option value="${value}">${escapeHtml(label)}</option>`).join('')}</select></label></div><div class="page-actions"><button class="button secondary" type="button" id="print-copy-order">Générer le bordereau</button></div></fieldset><label class="span-2">Note<textarea name="notes" rows="3" placeholder="Détail utile, référence de dossier…"></textarea></label></div><div class="page-actions"><button class="button secondary" type="button" id="cancel-courrier-item">Annuler</button><button class="button" type="submit" id="courrier-submit">Enregistrer</button></div></form><div id="courrier-summary" class="reminder-summary-boxes"></div>`:'';
